import React from 'react';
import { BarChart3 } from 'lucide-react';

/**
 * Top-10 MCX commodities by traded value, one session (01 Jan 2025).
 * Generated by scripts/mcx-turnover-from-bhavcopy.ts from data/mcx-bhavcopy-01jan2025.csv —
 * same numbers as the "MCX exchange turnover by commodity" chart in the
 * standalone Minervini Picks Dashboard artifact. Context for the MCX pick
 * in MinerviniPicksPanel: MCX (the exchange operator) earns fees on this
 * trading activity, so turnover is a proxy for its transaction revenue.
 * Re-run the script on a fresh bhavcopy export to refresh these figures.
 */
const MCX_TURNOVER: Array<{ symbol: string; valueLacs: number }> = [
  { symbol: 'CRUDEOIL', valueLacs: 1330739.55 },
  { symbol: 'NATURALGAS', valueLacs: 310478.03 },
  { symbol: 'GOLD', valueLacs: 261853.19 },
  { symbol: 'GOLDM', valueLacs: 83186.68 },
  { symbol: 'SILVER', valueLacs: 49747.87 },
  { symbol: 'COPPER', valueLacs: 37520.2 },
  { symbol: 'NATGASMINI', valueLacs: 23884.71 },
  { symbol: 'SILVERM', valueLacs: 23191.07 },
  { symbol: 'CRUDEOILM', valueLacs: 20277.05 },
  { symbol: 'SILVERMIC', valueLacs: 13922.98 },
];

const fmtLacs = (v: number) => `₹${v.toLocaleString('en-IN', { maximumFractionDigits: 0 })}L`;

export const McxTurnoverPanel: React.FC = () => {
  const maxVal = Math.max(...MCX_TURNOVER.map(r => r.valueLacs)) * 1.05;

  return (
    <div className="rounded-2xl border border-white/10 bg-[#0d1119] p-5">
      <h3 className="flex items-center gap-2 text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">
        <BarChart3 className="h-3.5 w-3.5 text-sky-400" /> MCX exchange turnover by commodity — 01 Jan 2025
      </h3>
      <p className="mt-1 text-[10px] text-slate-600">
        Value traded (₹ lacs) across MCX's commodity futures &amp; options for one session — context for the MCX pick above.
      </p>

      <div className="mt-4 flex flex-col gap-2">
        {MCX_TURNOVER.map(r => (
          <div key={r.symbol} className="grid grid-cols-[96px_1fr_72px] items-center gap-2.5 text-xs">
            <span className="text-right text-slate-500">{r.symbol}</span>
            <div className="h-[18px] overflow-hidden rounded bg-white/5">
              <div
                className="h-full rounded bg-sky-400/70"
                style={{ width: `${Math.max((r.valueLacs / maxVal) * 100, 1)}%` }}
              />
            </div>
            <span className="tabular-nums text-slate-300">{fmtLacs(r.valueLacs)}</span>
          </div>
        ))}
      </div>
    </div>
  );
};
